'use client';

import * as React from 'react';

import { Toast as BaseToast } from '@base-ui/react/toast';
import * as stylex from '@stylexjs/stylex';

import { space, fontSize, lineHeight, fontWeight, z, duration, easing, stroke, container } from '@/lib/constants.stylex';
import { colors, font, radius, shadow } from '@/lib/tokens.stylex';

/** The manager behind the imperative `toast` API — pass to `useToast` consumers if needed. */
export const toastManager = BaseToast.createToastManager();

type ToastAddOptions = Omit<
  Parameters<typeof toastManager.add>[0],
  'title'
>;

function addToast(
  title: React.ReactNode,
  options?: ToastAddOptions & { type?: string }
) {
  return toastManager.add({ title, ...options });
}

/**
 * Imperative API, callable anywhere — event handlers, stores, outside React:
 * `toast('Saved')`, `toast.error('Failed', { description: '…' })`,
 * `toast.promise(save(), { loading: '…', success: '…', error: '…' })`.
 * Requires `ToastProvider` + `Toaster` to be mounted (e.g. in the root layout).
 */
export const toast = Object.assign(addToast, {
  success: (title: React.ReactNode, options?: ToastAddOptions) =>
    addToast(title, { ...options, type: 'success' }),
  error: (title: React.ReactNode, options?: ToastAddOptions) =>
    addToast(title, { ...options, type: 'error' }),
  promise: toastManager.promise.bind(toastManager),
  update: toastManager.update.bind(toastManager),
  close: toastManager.close.bind(toastManager),
});

/** Hook form of the same API: `const t = useToast(); t.add({ title })`. */
export function useToast() {
  return BaseToast.useToastManager();
}

// Wired to the shared manager so the imperative `toast` reaches it; pass your
// own `toastManager` to opt out.
export function ToastProvider(
  props: React.ComponentPropsWithoutRef<typeof BaseToast.Provider>
) {
  return <BaseToast.Provider toastManager={toastManager} {...props} />;
}

function ToastList({
  swipeDirection,
}: {
  swipeDirection: React.ComponentPropsWithoutRef<
    typeof BaseToast.Root
  >['swipeDirection'];
}) {
  const { toasts } = BaseToast.useToastManager();
  return toasts.map((t) => (
    <BaseToast.Root
      key={t.id}
      toast={t}
      swipeDirection={swipeDirection}
      {...stylex.props(styles.root)}
    >
      <div {...stylex.props(styles.content)}>
        <div {...stylex.props(styles.text)}>
          <BaseToast.Title {...stylex.props(styles.title)} />
          <BaseToast.Description {...stylex.props(styles.description)} />
        </div>
        <BaseToast.Action {...stylex.props(styles.action)} />
        <BaseToast.Close aria-label="Close" {...stylex.props(styles.close)}>
          <svg
            width="12"
            height="12"
            viewBox={`0 0 12 12`}
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            aria-hidden
          >
            <path d={`m2 2 8 8M10 2l-8 8`} />
          </svg>
        </BaseToast.Close>
      </div>
    </BaseToast.Root>
  ));
}

export interface ToasterProps {
  /** Direction(s) a toast can be swiped to dismiss. */
  swipeDirection?: React.ComponentPropsWithoutRef<
    typeof BaseToast.Root
  >['swipeDirection'];
  /** StyleX styles for the viewport, merged last. */
  style?: stylex.StyleXStyles;
}

/**
 * Mount once (inside ToastProvider) — renders the toast stack. Toasts pile up
 * behind the newest one; hovering or focusing the stack expands it. Swipe
 * down/right (touch or mouse) to dismiss.
 */
export function Toaster({
  swipeDirection = ['down', 'right'],
  style,
}: ToasterProps) {
  return (
    <BaseToast.Portal>
      <BaseToast.Viewport {...stylex.props(styles.viewport, style)}>
        <ToastList swipeDirection={swipeDirection} />
      </BaseToast.Viewport>
    </BaseToast.Portal>
  );
}


const styles = stylex.create({
  viewport: {
    bottom: space.s4,
    position: 'fixed',
    right: space.s4,
    width: container.md,
    zIndex: z.toast,
  },
  root: {
    // Behind toasts peek out above the frontmost one, shrunk slightly; swipe
    // movement rides along via the Base UI-provided CSS variables.
    '--toast-gap': space.s2,
    alignItems: 'flex-start',
    backgroundColor: colors.popover,
    // Error toasts get a destructive accent; other types render neutrally
    // (matches sonner's default look — no per-type colors without opt-in).
    borderColor: { default: colors.border, '[data-type="error"]': colors.destructive },
    borderRadius: radius.md,
    borderStyle: 'solid',
    borderWidth: stroke.border,
    bottom: 0,
    boxShadow: shadow.lg,
    boxSizing: 'border-box',
    color: colors.popoverForeground,
    display: 'flex',
    fontFamily: font.sans,
    // Behind-card content fades in when the stack expands (read by .content).
    '--toast-content-visible': { default: null, '[data-expanded]': '1' },
    // All toasts share the frontmost height while collapsed so the stack
    // reads as one card with edges peeking out.
    height: {
      default: 'var(--toast-frontmost-height)',
      '[data-expanded]': 'var(--toast-height)',
    },
    // [data-limited]: over the provider's limit — kept mounted, hidden by us.
    opacity: {
      default: 1,
      '[data-limited]': 0,
      '[data-starting-style]': 0,
      '[data-ending-style]': 0,
    },
    overflow: 'hidden',
    padding: space.s4,
    position: 'absolute',
    right: 0,
    // Later conditions win at equal specificity: the closed pose overrides
    // the expanded/collapsed stack pose while entering or leaving.
    transform: {
      default: `translateX(var(--toast-swipe-movement-x, 0px)) translateY(calc(var(--toast-swipe-movement-y, 0px) + min(var(--toast-index), 10) * -1 * var(--toast-gap))) scale(calc(max(0.8, 1 - var(--toast-index) * 0.05)))`,
      '[data-expanded]': `translateX(var(--toast-swipe-movement-x, 0px)) translateY(calc(var(--toast-swipe-movement-y, 0px) - var(--toast-offset-y) - var(--toast-index) * var(--toast-gap)))`,
      '[data-starting-style]': `translateY(calc(100% + ${space.s4}))`,
      '[data-ending-style]': `translateY(calc(100% + ${space.s4}))`,
    },
    transformOrigin: 'center bottom',
    transitionDuration: { default: duration.slow, '[data-swiping]': '0s' },
    transitionProperty: {
      default: 'transform, opacity, height',
      '@media (prefers-reduced-motion: reduce)': 'opacity',
    },
    transitionTimingFunction: easing.out,
    width: '100%',
    zIndex: `calc(${z.toast} - var(--toast-index))`,
  },
  content: {
    alignItems: 'flex-start',
    display: 'flex',
    gap: space.s2,
    justifyContent: 'space-between',
    // Behind toasts hide their content so the collapsed stack shows only the
    // frontmost card's text; expanding reveals every card (custom property set
    // by rootExpanded).
    opacity: `var(--toast-content-visible, calc(max(0, 1 - var(--toast-index))))`,
    transitionDuration: duration.fast,
    transitionProperty: 'opacity',
    width: '100%',
  },
  text: {
    display: 'flex',
    flex: 1,
    flexDirection: 'column',
    gap: space.s1,
  },
  title: {
    fontSize: fontSize.sm,
    fontWeight: fontWeight.semibold,
    lineHeight: lineHeight.tight,
    margin: 0,
  },
  description: {
    color: colors.mutedForeground,
    fontSize: fontSize.sm,
    lineHeight: lineHeight.snug,
    margin: 0,
  },
  action: {
    alignItems: 'center',
    backgroundColor: {
      default: 'transparent',
      ':hover': colors.accent,
    },
    borderColor: colors.border,
    borderRadius: radius.sm,
    borderStyle: 'solid',
    borderWidth: stroke.border,
    color: colors.foreground,
    cursor: 'pointer',
    display: 'inline-flex',
    flexShrink: 0,
    fontFamily: font.sans,
    fontSize: fontSize.xs,
    fontWeight: fontWeight.medium,
    height: space.s6,
    justifyContent: 'center',
    outline: { default: 'none', ':focus-visible': `${stroke.focus} solid ${colors.ring}` },
    paddingInline: space.s2,
  },
  close: {
    alignItems: 'center',
    backgroundColor: {
      default: 'transparent',
      ':hover': colors.accent,
    },
    borderRadius: radius.sm,
    borderStyle: 'none',
    color: colors.mutedForeground,
    cursor: 'pointer',
    display: 'inline-flex',
    flexShrink: 0,
    height: space.s6,
    justifyContent: 'center',
    outline: { default: 'none', ':focus-visible': `${stroke.focus} solid ${colors.ring}` },
    padding: 0,
    width: space.s6,
  },
});
